definition.script:
pipeline {
    agent any

    options {
        timeout(time: 30, unit: 'MINUTES')
        disableConcurrentBuilds()
        buildDiscarder(logRotator(numToKeepStr: '10'))
    }

    parameters {
        choice(
            name: 'ACTION',
            choices: ['plan', 'apply', 'destroy'],
            description: 'Terraform action to perform'
        )
        string(
            name: 'INSTANCE_TYPE',
            defaultValue: 't3.micro',
            description: 'EC2 instance type for the target instance'
        )
    }

    environment {
        TF_DIR     = 'infra/target-ec2'
        TF_KEY     = 'jenkins-terraform-ec2/target-ec2/terraform.tfstate'
        AWS_REGION = 'us-east-1'
    }

    stages {
        stage('Terraform Init') {
            steps {
                withCredentials([
                    usernamePassword(
                        credentialsId: 'aws-credentials',
                        usernameVariable: 'AWS_ACCESS_KEY_ID',
                        passwordVariable: 'AWS_SECRET_ACCESS_KEY'
                    ),
                    string(credentialsId: 'TF_STATE_BUCKET', variable: 'BUCKET'),
                    string(credentialsId: 'SSH_PUBLIC_KEY', variable: 'TF_VAR_ssh_public_key')
                ]) {
                    sh '''
                        cd ${TF_DIR}
                        terraform init -input=false -reconfigure \
                            -backend-config="bucket=${BUCKET}" \
                            -backend-config="key=${TF_KEY}" \
                            -backend-config="region=${AWS_REGION}"
                    '''
                }
            }
        }

        stage('Terraform Plan') {
            steps {
                withCredentials([
                    usernamePassword(
                        credentialsId: 'aws-credentials',
                        usernameVariable: 'AWS_ACCESS_KEY_ID',
                        passwordVariable: 'AWS_SECRET_ACCESS_KEY'
                    ),
                    string(credentialsId: 'SSH_PUBLIC_KEY', variable: 'TF_VAR_ssh_public_key')
                ]) {
                    sh '''
                        cd ${TF_DIR}
                        terraform plan -input=false \
                            -var="instance_type=${INSTANCE_TYPE}" \
                            -out=tfplan
                    '''
                }
            }
        }

        stage('Approval') {
            when {
                expression { params.ACTION == 'apply' || params.ACTION == 'destroy' }
            }
            steps {
                input message: "Approve Terraform ${params.ACTION}?", ok: 'Proceed'
            }
        }

        stage('Terraform Apply') {
            when { expression { params.ACTION == 'apply' } }
            steps {
                withCredentials([
                    usernamePassword(
                        credentialsId: 'aws-credentials',
                        usernameVariable: 'AWS_ACCESS_KEY_ID',
                        passwordVariable: 'AWS_SECRET_ACCESS_KEY'
                    ),
                    string(credentialsId: 'SSH_PUBLIC_KEY', variable: 'TF_VAR_ssh_public_key')
                ]) {
                    sh 'cd ${TF_DIR} && terraform apply -input=false tfplan'
                    sh 'cd ${TF_DIR} && echo "=== Outputs ===" && terraform output'
                }
            }
        }

        stage('Terraform Destroy') {
            when { expression { params.ACTION == 'destroy' } }
            steps {
                withCredentials([
                    usernamePassword(
                        credentialsId: 'aws-credentials',
                        usernameVariable: 'AWS_ACCESS_KEY_ID',
                        passwordVariable: 'AWS_SECRET_ACCESS_KEY'
                    ),
                    string(credentialsId: 'SSH_PUBLIC_KEY', variable: 'TF_VAR_ssh_public_key')
                ]) {
                    sh '''
                        cd ${TF_DIR}
                        terraform destroy -input=false -auto-approve \
                            -var="instance_type=${INSTANCE_TYPE}"
                    '''
                }
            }
        }
    }

    post {
        success { echo "Pipeline completed: ACTION=${params.ACTION}" }
        failure { echo "Pipeline FAILED: ACTION=${params.ACTION}" }
        always  { cleanWs() }
    }
}
